public enum McpTransport: Codable, Hashable, Sendable {
    case stdio(Stdio)
    case http(Http)

    public var type: String {
        switch self {
        case .stdio: Stdio.type
        case .http(let value): value.type.rawValue
        }
    }

    private enum DiscriminatorKey: String, CodingKey {
        case type
    }

    public init(from decoder: any Decoder) throws {
        let container = try decoder.container(keyedBy: DiscriminatorKey.self)
        let tag = try container.decode(String.self, forKey: .type)
        switch tag {
        case "stdio": self = .stdio(try Stdio(from: decoder))
        case "http", "sse": self = .http(try Http(from: decoder))
        default: throw DecodingError.dataCorruptedError(forKey: .type, in: container, debugDescription: "unknown McpTransport type \(tag)")
        }
    }

    public func encode(to encoder: any Encoder) throws {
        switch self {
        case .stdio(let value): try value.encode(to: encoder)
        case .http(let value): try value.encode(to: encoder)
        }
    }

    public struct Stdio: Codable, Hashable, Sendable {
        public static let type = "stdio"

        public var command: String
        public var args: [String]
        public var env: [String: EnvValue]
        public var cwd: String?

        public init(
            command: String,
            args: [String],
            env: [String: EnvValue],
            cwd: String?
        ) {
            self.command = command
            self.args = args
            self.env = env
            self.cwd = cwd
        }

        private enum CodingKeys: String, CodingKey {
            case type
            case command
            case args
            case env
            case cwd
        }

        public init(from decoder: any Decoder) throws {
            let container = try decoder.container(keyedBy: CodingKeys.self)
            try container.decodeConstant(Self.type, forKey: .type)
            command = try container.decode(String.self, forKey: .command)
            args = try container.decode([String].self, forKey: .args)
            env = try container.decode([String: EnvValue].self, forKey: .env)
            cwd = try container.decode(String?.self, forKey: .cwd)
        }

        public func encode(to encoder: any Encoder) throws {
            var container = encoder.container(keyedBy: CodingKeys.self)
            try container.encode(Self.type, forKey: .type)
            try container.encode(command, forKey: .command)
            try container.encode(args, forKey: .args)
            try container.encode(env, forKey: .env)
            try container.encode(cwd, forKey: .cwd)
        }

        public enum EnvValue: Codable, Hashable, Sendable {
            case string(String)
            case secretRef(SecretRef)

            public init(from decoder: any Decoder) throws {
                let container = try decoder.singleValueContainer()
                if let value = try? container.decode(String.self) {
                    self = .string(value)
                } else if let value = try? container.decode(SecretRef.self) {
                    self = .secretRef(value)
                } else {
                    throw DecodingError.dataCorruptedError(in: container, debugDescription: "EnvValue matches none of its variants")
                }
            }

            public func encode(to encoder: any Encoder) throws {
                var container = encoder.singleValueContainer()
                switch self {
                case .string(let value): try container.encode(value)
                case .secretRef(let value): try container.encode(value)
                }
            }
        }
    }

    public struct Http: Codable, Hashable, Sendable {
        public var type: TypeValue
        public var url: String
        public var headers: [String: HeadersValue]

